    patient?.patientAppId ?? patient?.patientAppID ?? patient?.PatientAppId ?? patient?.id ?? null;

const RESCHEDULE_REASON_OPTIONS = [
    { value: '', label: 'Select reason' },
    { value: 'Patient request', label: 'Patient request' },
    { value: 'Doctor unavailable', label: 'Doctor unavailable' },
    { value: 'Schedule conflict', label: 'Schedule conflict' },
    { value: 'Emergency', label: 'Emergency' },
    { value: 'Other', label: 'Other' },
];

const CANCELLATION_REASON_OPTIONS = [
    { value: '', label: 'Select reason' },
    ...CANCEL_REASONS,
];

const AppointmentTimeCell = ({
    patient,
    appStatus,
    isEditing,
    onStartEdit,
    onCancelEdit,
    onTimeUpdated,
    appointmentDateFallback,
}) => {
    const dispatch = useDispatch();
    const { userProfile } = useProfile();
    const isLocked = isAppointmentCompleted(appStatus);
    const patientAppId = getPatientAppIdFromRow(patient);
    const doctorId = patient?.doctorId || patient?.doctorID;
    const rawTime = patient?.appointmentTime;
    const appointmentDate = toApiDateValue(patient?.appointmentDate ?? patient?.AppointmentDate, appointmentDateFallback);
    const [displayTime, setDisplayTime] = useState(() => formatAppointmentTime(rawTime));
    const [slots, setSlots] = useState([]);
    const [slotsLoading, setSlotsLoading] = useState(false);
    const [hasSchedule, setHasSchedule] = useState(false);
    const [slotInterval, setSlotInterval] = useState(null);
    const [saving, setSaving] = useState(false);
    const [scheduleModalOpen, setScheduleModalOpen] = useState(false);
    const [rescheduleReason, setRescheduleReason] = useState('');
    const [additionalNote, setAdditionalNote] = useState('');
    const [selectedSlot, setSelectedSlot] = useState(null);
    const [cancelModalOpen, setCancelModalOpen] = useState(false);
    const [rescheduleModalOpen, setRescheduleModalOpen] = useState(false);
    const [cancellationReason, setCancellationReason] = useState('');
    const [cancellationNote, setCancellationNote] = useState('');
    const [cancelling, setCancelling] = useState(false);

    useEffect(() => {
        setDisplayTime(formatAppointmentTime(rawTime));
    }, [rawTime]);

    useEffect(() => {
        if (!isEditing) {
            setRescheduleReason('');
            setAdditionalNote('');
            setSelectedSlot(null);
            setCancelModalOpen(false);
            setRescheduleModalOpen(false);
            setCancellationReason('');
            setCancellationNote('');
        }
    }, [isEditing]);

    const loadSlots = async () => {
        if (!doctorId || !appointmentDate) {
            setSlots([]);
            setHasSchedule(false);
            setSlotInterval(null);
            return;
        }

        setSlotsLoading(true);
        try {
            const response = await getAppointmentSlots({
                doctorId,
                appointmentDate,
                currentPatientAppId: patientAppId,
            });
            const normalized = normalizeAppointmentSlotsResponse(response);
            setSlots(normalized.slots);
            setHasSchedule(Boolean(normalized.hasSchedule));
            setSlotInterval(normalized.intervalMinutes ?? null);
        } catch (error) {
            console.error('Failed to load appointment slots:', error);
            setSlots([]);
            setHasSchedule(false);
            setSlotInterval(null);
        } finally {
            setSlotsLoading(false);
        }
    };

    useEffect(() => {
        if (!isEditing) return;
        loadSlots();
    }, [isEditing, doctorId, appointmentDate, patientAppId]);

    useEffect(() => {
        if (!isEditing || !slots.length) return;
        const currentSlot = slots.find((slot) => slot.status === 'current')
            || slots.find((slot) => formatAppointmentTime(slot.time) === displayTime);
        if (currentSlot) {
            setSelectedSlot((prev) => prev || currentSlot);
        }
    }, [isEditing, slots, displayTime]);

    const handleSlotClick = (slot) => {
        if (!slot || (slot.status !== 'available' && slot.status !== 'current')) {
            return;
        }
        setSelectedSlot(slot);
    };

    const handleUpdateAppointment = async () => {
        if (!patientAppId || !selectedSlot) {
            Swal.fire({
                title: 'Select a slot',
                text: 'Please select an available time slot before updating.',
                icon: 'info',
                timer: 1800,
                showConfirmButton: false,
            });
            return;
        }

        setSaving(true);
        try {
            const response = await updateAppointmentTime({
                patientAppId,
                appointmentTime: selectedSlot.time,
                appointmentDate,
                reasonForReschedule: rescheduleReason || undefined,
                additionalNote: additionalNote.trim() || undefined,
            });
            setDisplayTime(formatAppointmentTime(selectedSlot.time));
            onCancelEdit();
            onTimeUpdated?.();
            const saved = response?.data ?? response;
            Swal.fire({
                title: 'Updated!',
                text: saved?.message || 'Appointment time updated. This does not notify the patient. Reschedule is the patient-notified path.',
                icon: 'success',
                timer: 2200,
                showConfirmButton: false,
            });
        } catch (error) {
            const errorMessage = error?.response?.data?.message || error?.message || 'Failed to update appointment time';
            Swal.fire({
                title: 'Error!',
                text: errorMessage,
                icon: 'error',
                timer: 2000,
                showConfirmButton: false,
            });
        } finally {
            setSaving(false);
        }
    };

    const closeCancelModal = () => {
        if (cancelling) return;
        setCancelModalOpen(false);
        setCancellationReason('');
        setCancellationNote('');
    };

    const handleConfirmCancelAppointment = async () => {
        if (!patientAppId) {
            Swal.fire({
                title: 'Error!',
                text: 'Appointment ID not found',
                icon: 'error',
                timer: 2000,
                showConfirmButton: false,
            });
            return;
        }
        if (!cancellationReason) {
            Swal.fire({
                title: 'Select a reason',
                text: 'Please select a cancellation reason.',
                icon: 'info',
                timer: 1800,
                showConfirmButton: false,
            });
            return;
        }
        if (cancellationReason === 'Other' && !cancellationNote.trim()) {
            Swal.fire({
                title: 'Details required',
                text: 'Add a note when the reason is Other.',
                icon: 'info',
                timer: 1800,
                showConfirmButton: false,
            });
            return;
        }

        setCancelling(true);
        try {
            // Must use CancelAppointment (ReasonCode), not UpdateAppointmentStatus.
            const response = await cancelAppointment({
                patientAppId: Number(patientAppId),
                reasonCode: cancellationReason,
                reasonText: cancellationNote.trim() || undefined,
            });
            const failed =
                response?.success === false ||
                response?.Success === false ||
                (response?.statusCode != null && Number(response.statusCode) >= 400) ||
                (response?.StatusCode != null && Number(response.StatusCode) >= 400);
            if (failed) {
                throw new Error(
                    response?.message ||
                        response?.Message ||
                        'Failed to cancel appointment'
                );
            }
            setCancelModalOpen(false);
            setCancellationReason('');
            setCancellationNote('');
            onCancelEdit();
            onTimeUpdated?.();
            Swal.fire({
                title: 'Cancelled!',
                text: response?.message || response?.Message || 'Appointment has been cancelled.',
                icon: 'success',
                timer: 1500,
                showConfirmButton: false,
            });
        } catch (error) {
            const errorMessage =
                (typeof error === 'string' && error) ||
                error?.response?.data?.message ||
                error?.response?.data?.Message ||
                error?.message ||
                'Failed to cancel appointment';
            Swal.fire({
                title: 'Error!',
                text: errorMessage,
                icon: 'error',
                timer: 2800,
                showConfirmButton: true,
            });
        } finally {
            setCancelling(false);
        }
    };

    const editButtonId = `appointment-time-edit-${patientAppId}`;
    const patientName = patient?.name || patient?.patientName || 'Patient';
    const loggedInDoctorName = userProfile?.userName
        || userProfile?.user?.userName
        || userProfile?.name
        || [userProfile?.firstName, userProfile?.lastName].filter(Boolean).join(' ')
        || '';
    const rawDoctorName = patient?.doctorName
        || patient?.DoctorName
        || (typeof patient?.doctor === 'string' ? patient.doctor : '')
        || loggedInDoctorName
        || '';
    const doctorName = !String(rawDoctorName).trim()
        ? '—'
        : /^dr\.?\s/i.test(String(rawDoctorName).trim())
            ? String(rawDoctorName).trim()
            : `Dr. ${String(rawDoctorName).trim()}`;
    const appointmentTypeLabel = patient?.appointmentType
        || patient?.consultType
        || (String(appStatus || '').toUpperCase() === 'E-CONSULT' ? 'Tele Consultation' : 'In-Clinic');
    const appointmentSummaryWhen = (() => {
        const datePart = moment(appointmentDate, ['YYYY-MM-DD', DOB_DISPLAY_FORMAT], true);
        const timePart = selectedSlot?.label || displayTime || formatAppointmentTime(rawTime);
        if (datePart.isValid()) {
            return `${datePart.format('ddd, D MMM YYYY')}${timePart ? `, ${timePart}` : ''}`;
        }
        return [appointmentDate, timePart].filter(Boolean).join(', ') || '—';
    })();

    return (
        <>
            <div className="appointment-time-cell">
                <span className="appointment-time-value">{displayTime}</span>
                <span id={editButtonId} className="d-inline-block" tabIndex={isLocked ? 0 : undefined}>
                    <button
                        type="button"
                        className="btn btn-sm btn-soft-success edit-item-btn appointment-time-edit-btn"
                        onClick={onStartEdit}
                        disabled={isLocked}
                        style={isLocked ? { pointerEvents: 'none' } : undefined}
                        aria-label="Edit appointment"
                    >
                        <i className="ri-pencil-fill" aria-hidden="true" />
                    </button>
                </span>
                <UncontrolledTooltip placement="top" target={editButtonId}>
                    {isLocked ? COMPLETED_APPOINTMENT_LOCKED_MESSAGE : 'Edit appointment — update time, reschedule, or cancel'}
                </UncontrolledTooltip>
            </div>

            <Modal
                isOpen={isEditing && !isLocked}
                toggle={onCancelEdit}
                centered
                size="lg"
                className="patient-list-modal appointment-time-edit-modal"
                backdrop="static"
            >
                <ModalHeader className="patient-list-modal__header" toggle={onCancelEdit}>
                    <span className="patient-list-modal__title patient-list-modal__title--simple">
                        <i className="ri-calendar-event-line" style={{ color: '#25a0e2', fontSize: 15 }} />
                        <span className="patient-list-modal__title-text">Edit Appointment</span>
                    </span>
                </ModalHeader>
                <ModalBody>
                    <div className="appointment-time-patient-chip mb-3">
                        <i className="ri-user-3-line" aria-hidden="true" />
                        <span>{patientName}</span>
                    </div>
                    <p className="text-muted small mb-3">
                        Update the slot on this day list, reschedule with patient notice, or cancel the visit.
                    </p>
                    <div className="row g-3 mb-3">
                        <div className="col-md-6">
                            <Label className="form-label appointment-time-edit-modal__label">
                                <i className="ri-calendar-line" />
                                Appointment Date
                            </Label>
                            <Input readOnly disabled value={appointmentDate || '—'} />
                        </div>
                        <div className="col-md-6">
                            <Label className="form-label appointment-time-edit-modal__label">
                                <i className="ri-timer-line" />
                                Slot Interval
                            </Label>
                            <Input
                                readOnly
                                disabled
                                className="appointment-slot-interval-display"
                                value={
                                    hasSchedule && slotInterval
                                        ? formatSlotIntervalLabel(slotInterval)
                                        : 'Not configured'
                                }
                            />
                        </div>
                        <div className="col-md-6">
                            <Label className="form-label appointment-time-edit-modal__label">
                                <i className="ri-refresh-line" />
                                Reason
                            </Label>
                            <Input
                                type="select"
                                value={rescheduleReason}
                                onChange={(e) => setRescheduleReason(e.target.value)}
                                disabled={saving || cancelling}
                            >
                                {RESCHEDULE_REASON_OPTIONS.map((option) => (
                                    <option key={option.label} value={option.value} disabled={option.value === ''}>
                                        {option.label}
                                    </option>
                                ))}
                            </Input>
                        </div>
                        <div className="col-md-6">
                            <Label className="form-label appointment-time-edit-modal__label">
                                <i className="ri-sticky-note-line" />
                                Additional Note
                            </Label>
                            <Input
                                type="text"
                                value={additionalNote}
                                onChange={(e) => setAdditionalNote(e.target.value)}
                                disabled={saving || cancelling}
                                placeholder=""
                            />
                        </div>
                    </div>
                    {!doctorId ? (
                        <div className="text-muted">Doctor information is missing for this appointment.</div>
                    ) : !hasSchedule ? (
                        <div className="border rounded p-3 bg-light">
                            <p className="text-muted mb-2">No slot schedule exists for this date.</p>
                            <Button
                                type="button"
                                size="sm"
                                className="new-appointment-modal__setup-btn"
                                onClick={() => setScheduleModalOpen(true)}
                            >
                                Set up slots for this date
                            </Button>
                        </div>
                    ) : (
                        <div className="appointment-slot-panel">
                            <AppointmentSlotGrid
                                slots={slots}
                                loading={slotsLoading || saving}
                                selectedTime={selectedSlot?.time}
                                onSlotClick={handleSlotClick}
                                emptyMessage="No slots configured for this date."
                                showSummaryBar
                            />
                        </div>
                    )}
                    <div className="text-muted mt-2" style={{ fontSize: '0.875rem' }}>
                        Select an available slot, then click Update time (no patient notice). Use Reschedule to move the visit and notify the patient.
                    </div>
                </ModalBody>
                <ModalFooter className="appointment-time-edit-modal__footer appointment-time-edit-modal__footer--actions">
                    <button
                        type="button"
                        className="btn btn-soft-danger modal-action-btn"
                        onClick={() => setCancelModalOpen(true)}
                        disabled={saving || cancelling}
                    >
                        <i className="ri-calendar-close-line align-middle" aria-hidden />
                        <span>Cancel</span>
                    </button>
                    <button
                        type="button"
                        className="btn btn-soft-info modal-action-btn"
                        onClick={() => setRescheduleModalOpen(true)}
                        disabled={saving || cancelling || !patientAppId}
                    >
                        <i className="ri-calendar-schedule-line align-middle" aria-hidden />
                        <span>Reschedule</span>
                    </button>
                    <ModalActionButton
                        action="update"
                        onClick={handleUpdateAppointment}
                        disabled={saving || cancelling || !selectedSlot || !hasSchedule}
                        loading={saving}
                        loadingLabel="Update time"
                    >
                        Update time
                    </ModalActionButton>
                </ModalFooter>
            </Modal>

            <RescheduleModal
                isOpen={rescheduleModalOpen}
                toggle={() => setRescheduleModalOpen(false)}
                patientAppId={patientAppId}
                doctorId={doctorId}
                appointmentDate={appointmentDate}
                appointmentTime={rawTime}
                onSaved={() => {
                    setRescheduleModalOpen(false);
                    onCancelEdit();
                    onTimeUpdated?.();
                }}
            />

            <Modal
                isOpen={cancelModalOpen}
                toggle={closeCancelModal}
                centered
                className="patient-list-modal cancel-appointment-modal"
                backdrop="static"
            >
                <ModalHeader className="patient-list-modal__header" toggle={closeCancelModal}>
                    <span className="patient-list-modal__title patient-list-modal__title--simple">
                        <span className="patient-list-modal__title-text">Cancel Appointment</span>
                    </span>
                </ModalHeader>
                <ModalBody>
                    <div className="cancel-appointment-modal__warning">
                        <i className="ri-error-warning-fill" aria-hidden="true" />
                        <div>
                            <p className="cancel-appointment-modal__warning-title mb-2">
                                Are you sure you want to cancel this appointment?
                            </p>
                            <div className="cancel-appointment-modal__summary">
                                <span className="cancel-appointment-modal__avatar" aria-hidden="true">
                                    <i className="ri-user-3-line" />
                                </span>
                                <div className="cancel-appointment-modal__summary-text">
                                    <div className="cancel-appointment-modal__patient">{patientName}</div>
                                    <div className="cancel-appointment-modal__meta">{doctorName}</div>
                                    <div className="cancel-appointment-modal__meta">
                                        {appointmentSummaryWhen}
                                        {' • '}
                                        {appointmentTypeLabel}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="mt-3">
                        <Label className="form-label appointment-time-edit-modal__label">
                            Cancellation Reason
                        </Label>
                        <Input
                            type="select"
                            value={cancellationReason}
                            onChange={(e) => setCancellationReason(e.target.value)}
                            disabled={cancelling}
                        >
                            {CANCELLATION_REASON_OPTIONS.map((option) => (
                                <option key={option.label} value={option.value} disabled={option.value === ''}>
                                    {option.label}
                                </option>
                            ))}
                        </Input>
                    </div>
                    <div className="mt-3">
                        <Label className="form-label appointment-time-edit-modal__label">
                            Additional Note
                        </Label>
                        <Input
                            type="textarea"
                            rows={3}
                            value={cancellationNote}
                            onChange={(e) => setCancellationNote(e.target.value)}
                            disabled={cancelling}
                        />
                    </div>
                </ModalBody>
                <ModalFooter className="cancel-appointment-modal__footer">
                    <button
                        type="button"
                        className="btn btn-outline-primary cancel-appointment-modal__keep-btn"
                        onClick={closeCancelModal}
                        disabled={cancelling}
                    >
                        <i className="ri-calendar-check-line align-middle" aria-hidden />
                        <span>Keep Appointment</span>
                    </button>
                    <button
                        type="button"
                        className="btn btn-danger cancel-appointment-modal__confirm-btn"
                        onClick={handleConfirmCancelAppointment}
                        disabled={cancelling}
                    >
                        <i className="ri-calendar-close-line align-middle" aria-hidden />
                        <span>{cancelling ? 'Cancelling...' : 'Cancel Appointment'}</span>
                    </button>
                </ModalFooter>
            </Modal>

            <DailyScheduleSetupModal
                isOpen={scheduleModalOpen}
                doctorId={doctorId}
                scheduleDate={appointmentDate}
                requireSave={false}
                onClose={() => setScheduleModalOpen(false)}
                onSaved={() => {
                    setScheduleModalOpen(false);
                    loadSlots();
                }}
            />
        </>
    );
};

/** Local calendar day as YYYY-MM-DDT00:00:00.000Z — matches Widgets dashboardQueryDateIso (avoids IST day shift). */
const toDashboardAppointmentDateIso = (displayDateStr) => {
    const parsed = moment(displayDateStr, [DOB_DISPLAY_FORMAT, 'MM/DD/YYYY', 'DD-MM-YYYY', 'D-M-YYYY', 'YYYY-MM-DD'], true);
    const day = parsed.isValid() ? parsed.format('YYYY-MM-DD') : moment().format('YYYY-MM-DD');
    return formatCalendarDateForApi(day);
};

const triggerBlobDownload = (blob, fileName) => {
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', fileName);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
};

const downloadBase64File = (base64Content, fileName, contentType = 'application/octet-stream') => {
    if (!base64Content) return;
    const byteCharacters = atob(base64Content);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i += 1) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const blob = new Blob([new Uint8Array(byteNumbers)], { type: contentType });
    triggerBlobDownload(blob, fileName);
};

