                            const isSelected = selectedRemedyFromCommonUncommon && selectedRemedyFromCommonUncommon.remedyId === remedy.remedyId;
                            const isExpanded = expandedCommonItems.has(normalizeAccordionRemedyId(remedy.remedyId));

