export const getDailySchedule = async (params) => {
  try {
    return await nigahomeoAPI.get(url.GET_DAILY_SCHEDULE, params);
  } catch (error) {
    const message = typeof error === 'string' ? error : (error?.message || '');
    if (message.toLowerCase().includes('not found')) {
      return null;
    }
    throw error;
  }
};
