import React, { useEffect, useState } from 'react';
import AdminListPagination from '../../../../Components/Common/AdminListPagination';
import { Card, CardBody, CardHeader, Col, Container, Row, Spinner } from 'reactstrap';
import { Link } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import Swal from 'sweetalert2';
import { getLabTestList } from '../../../../slices/admin/labtests/thunk';
import { deletePatientLabTest } from '../../../../helpers/realbackend_helper';
import { exportListTableCsv } from '../../../../helpers/listExport';

const ListLabsImaging = () => {
  const dispatch = useDispatch();

  const [currentPage, setCurrentPage] = useState(1);
  const [searchQuery, setSearchQuery] = useState('');
  const pageSize = 10;

  const labTestLoading = useSelector((state) => state?.LabTest?.labTestLoading || false);
  const labTests = useSelector((state) => state?.LabTest?.labTestList?.resultObject) || [];
  const totalPages = useSelector((state) => state?.LabTest?.labTestList?.totalPageCount || 1);
  const totalRecords = useSelector(
    (state) => state?.LabTest?.labTestList?.totalRecordCount || labTests.length || 0
  );

  useEffect(() => {
    dispatch(getLabTestList({
      PageNumber: currentPage,
      PageSize: pageSize,
      queryString: searchQuery,
    }));
  }, [currentPage, searchQuery, dispatch]);

  const handleSearchChange = (event) => {
    setSearchQuery(event.target.value);
    setCurrentPage(1);
  };



  const handleDelete = async (test) => {
    const confirm = await Swal.fire({
      title: 'Delete lab / imaging test?',
      text: `"${test.labTestName || 'This test'}" will be removed from the list.`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      confirmButtonText: 'Yes, delete',
    });
    if (!confirm.isConfirmed) return;
    try {
      const response = await deletePatientLabTest(test.patientLabTestId);
      Swal.fire('Deleted', typeof response === 'string' ? response : 'Lab test deleted successfully.', 'success');
      dispatch(getLabTestList({ PageNumber: currentPage, PageSize: pageSize, queryString: searchQuery }));
    } catch (error) {
      const message = typeof error === 'string' ? error : error?.message;
      Swal.fire('Error', message || 'The lab test could not be deleted.', 'error');
    }
  };

  const rowStart = (currentPage - 1) * pageSize;

  document.title = 'List Labs & Imaging';
  return (
    <React.Fragment>
      <div className="page-content">
        <Container fluid>
          <Row>
            <Col lg={12}>
              <Card className="patient-list-modal admin-existance-list">
                <CardHeader className="border-0">
                  <div className="admin-list-toolbar d-flex align-items-center justify-content-between gap-2 flex-wrap w-100">
                    <div className="patient-list-modal__search flex-shrink-0">
                      <i className="ri-search-line patient-list-modal__search-icon" aria-hidden="true" />
                      <input
                        type="text"
                        className="form-control form-control-sm"
                        placeholder="Search..."
                        value={searchQuery}
                        onChange={handleSearchChange}
                      />
                    </div>
                    <div className="admin-list-toolbar__actions d-flex align-items-center gap-2 flex-shrink-0 ms-auto">
                      <button type="button" className="btn btn-sm admin-list-btn admin-list-btn--import" disabled title="Import is not available for this list yet">
                        <i className="ri-upload-2-line align-middle me-1" aria-hidden="true" />
                        Import
                      </button>
                      <button type="button" className="btn btn-sm admin-list-btn admin-list-btn--export" onClick={(e) => exportListTableCsv(e)}>
                        <i className="ri-download-2-line align-middle me-1" aria-hidden="true" />
                        Export
                      </button>
                      <Link to="/admin/addlabsimaging" className="d-inline-flex">
                        <button type="button" className="btn btn-sm admin-list-btn admin-list-btn--new">
                          <i className="ri-add-line align-middle me-1" aria-hidden="true" />
                          New
                        </button>
                      </Link>
                    </div>
                  </div>
                </CardHeader>
                <CardBody>
                  <div className="table-responsive patient-list-modal__table-wrap">
                    <table className="table mb-0 align-middle patient-list-modal__table" id="customerTable">
                      <thead>
                        <tr>
                          <th scope="col" className="text-center" style={{ width: '5%' }}>#</th>
                          <th scope="col">Test Name</th>
                          <th scope="col">Description</th>
                          <th scope="col" className="text-center" style={{ width: '12%' }}>Action</th>
                        </tr>
                      </thead>
                      {labTestLoading ? (
                        <tbody>
                          <tr>
                            <td colSpan="4" className="text-center">
                              <Spinner color="primary" size="sm" />
                            </td>
                          </tr>
                        </tbody>
                      ) : (
                        <tbody>
                          {labTests?.length > 0 ? (
                            labTests.map((test, index) => (
                              <tr key={test.patientLabTestId || index}>
                                <td className="text-center patient-list-modal__index">{rowStart + index + 1}</td>
                                <td>{test.labTestName || '—'}</td>
                                <td>{test.description || '—'}</td>
                                <td className="text-center">
                                  <div className="d-inline-flex gap-2">
                                    <div className="edit">
                                      <Link to="/admin/editlabsimaging" state={{ patientLabTestId: test.patientLabTestId }}>
                                        <button type="button" className="btn btn-sm btn-soft-success edit-item-btn" title="Edit">
                                          <i className="ri-pencil-fill" />
                                        </button>
                                      </Link>
                                    </div>
                                    <div className="remove">
                                      <button
                                        type="button"
                                        className="btn btn-sm btn-soft-danger remove-item-btn"
                                        title="Delete"
                                        onClick={() => handleDelete(test)}
                                      >
                                        <i className="ri-delete-bin-5-line" />
                                      </button>
                                    </div>
                                  </div>
                                </td>
                              </tr>
                            ))
                          ) : (
                            <tr>
                              <td colSpan="4" className="text-center text-muted py-4">
                                {searchQuery ? 'No lab tests match your search' : 'No Lab Tests Available'}
                              </td>
                            </tr>
                          )}
                        </tbody>
                      )}
                    </table>
                  </div>

                  <div className="d-flex align-items-center justify-content-between patient-list-modal__footer">
                    <div className="text-muted patient-list-modal__footer-text">
                      {labTestLoading
                        ? 'Loading...'
                        : `Showing ${labTests.length} of ${totalRecords} Results · Page ${currentPage} of ${totalPages}`}
                    </div>
                                        <AdminListPagination
                      currentPage={currentPage}
                      totalPages={totalPages}
                      onPage={setCurrentPage}
                    />
                  </div>
                </CardBody>
              </Card>
            </Col>
          </Row>
        </Container>
      </div>
    </React.Fragment>
  );
};

export default ListLabsImaging;
