import { UserRole } from "../Components/constants/roles";

export const getAuthUserInfo = () => {
  const authUserStr = sessionStorage.getItem("authUser");
  if (!authUserStr) {
    return null;
  }
  try {
    const obj = JSON.parse(authUserStr);
    return obj?.data ?? obj;
  } catch {
    return null;
  }
};

export const getUserRoleFromAuthStorage = () => {
  const userInfo = getAuthUserInfo();
  return userInfo?.role ?? null;
};

/** daysRemaining from Account/Login — stored in session authUser */
export const getPlanDaysRemaining = (user) => {
  const info = user && Object.keys(user).length > 0 ? user : getAuthUserInfo();
  const days = info?.daysRemaining;
  if (days == null || Number.isNaN(Number(days))) {
    return null;
  }
  return Number(days);
};

export const formatPlanDaysRemaining = (days) => {
  if (days == null) return "—";
  if (days <= 0) return "Expired";
  return `${days} ${days === 1 ? "Day" : "Days"} Remaining`;
};

export const getPlanDaysRemainingToneClass = (days) => {
  if (days == null) return "text-muted";
  if (days <= 0) return "text-danger";
  if (days <= 3) return "text-danger";
  if (days <= 7) return "text-warning";
  return "text-success";
};

export const getHomeDashboardPath = (role) => {
  const userRole = role ?? getUserRoleFromAuthStorage();
  if (userRole === UserRole.DOCTOR) {
    return "/doctordashboard";
  }
  if (userRole === UserRole.RECEPTION) {
    return "/reception";
  }
  if (userRole === UserRole.ACCOUNT) {
    return "/accountdashboard";
  }
  if (userRole === UserRole.PHARMACY || userRole === UserRole.PHARMACY_PARTNER) {
    return "/pharmacydashboard";
  }
  if (userRole === UserRole.PATIENT) {
    return "/patientdashboard";
  }
  return "/dashboard";
};

export const DOCTOR_DASHBOARD_OPEN_NEW_APPOINTMENT_EVENT = "doctor-dashboard:open-new-appointment";
export const DOCTOR_DASHBOARD_OPEN_BILLING_LIST_EVENT = "doctor-dashboard:open-billing-list";
export const DOCTOR_DASHBOARD_OPEN_SCHEDULE_CALENDAR_EVENT = "doctor-dashboard:open-schedule-calendar";
/** Fired after profile hours, daily schedule, or booking changes that affect appointment slots. */
export const DOCTOR_SCHEDULE_CHANGED_EVENT = "doctor-schedule:changed";

export const buildPatientSelectOption = (patient) => {
  if (!patient) {
    return null;
  }
  const value = patient.patientID ?? patient.patientId ?? patient.PatientId ?? patient.value;
  const label = patient.patientName ?? patient.label ?? patient.name;
  if (value == null || !String(label || "").trim()) {
    return null;
  }
  return { value, label: String(label).trim() };
};

export const dispatchOpenNewAppointmentModal = (patient = null) => {
  if (typeof window === "undefined") {
    return;
  }
  window.dispatchEvent(
    new CustomEvent(DOCTOR_DASHBOARD_OPEN_NEW_APPOINTMENT_EVENT, { detail: patient })
  );
};

export const dispatchOpenBillingListModal = () => {
  if (typeof window === "undefined") {
    return;
  }
  window.dispatchEvent(new CustomEvent(DOCTOR_DASHBOARD_OPEN_BILLING_LIST_EVENT));
};

export const dispatchOpenDoctorScheduleCalendar = () => {
  if (typeof window === "undefined") {
    return;
  }
  window.dispatchEvent(new CustomEvent(DOCTOR_DASHBOARD_OPEN_SCHEDULE_CALENDAR_EVENT));
};

export const dispatchDoctorScheduleChanged = (detail = null) => {
  if (typeof window === "undefined") {
    return;
  }
  window.dispatchEvent(new CustomEvent(DOCTOR_SCHEDULE_CHANGED_EVENT, { detail }));
};
