import React, { useEffect, useState } from 'react';
import AdminListPagination from '../../../../Components/Common/AdminListPagination';
import { CardHeader, Card, CardBody, Col, Container, Row, Spinner } from 'reactstrap';
import { Link } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { getUserList } from '../../../../slices/admin/users/thunk';
import Swal from 'sweetalert2';
import { downloadCsvEnvelope, exportUsers, importUsers, s4Message } from '../../../../helpers/s5Week5Api';
import { deleteUser as deleteUserApi } from '../../../../helpers/realbackend_helper';
import { getLoggedinUserInfo } from '../../../../helpers/api_helper';

const ListUser = () => {
  const dispatch = useDispatch();

  const [searchQuery, setSearchQuery] = useState('');
  const [verificationByUser, setVerificationByUser] = useState({});
  const [actionMessage, setActionMessage] = useState('');
  const fileRef = React.useRef(null);
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const userLoading = useSelector((state) => state?.User?.userLoading || false);
  const users = useSelector((state) => state?.User?.userList) || [];
  const totalRecords = useSelector((state) => state?.User?.totalCount || users.length || 0);
  const totalPages = useSelector((state) => state?.User?.totalPageCount || 1);

  useEffect(() => {
    dispatch(getUserList({
      queryString: searchQuery,
      PageNumber: currentPage,
      PageSize: pageSize,
    }));
  }, [dispatch, searchQuery, currentPage]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const response = await exportUsers();
        const csv = response?.csv || response?.Csv || '';
        const map = {};
        csv.split(/\r?\n/).slice(1).forEach((line) => {
          if (!line) return;
          const cells = line.split(',');
          map[cells[0]] = cells[6] || '';
        });
        if (!cancelled) setVerificationByUser(map);
      } catch {
        if (!cancelled) setVerificationByUser({});
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const handleExport = async () => {
    setActionMessage('');
    try {
      const response = await exportUsers();
      if (!downloadCsvEnvelope(response, 'users.csv')) setActionMessage('Export did not include a file.');
    } catch (err) {
      setActionMessage(s4Message(err));
    }
  };

  const handleImportFile = async (event) => {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file) return;
    setActionMessage('');
    try {
      const text = await file.text();
      const users = text.split(/\r?\n/).slice(1).map((line) => {
        const cells = line.split(',');
        return { userName: (cells[1] || cells[0] || '').replace(/"/g, '').trim(), emailId: (cells[2] || '').replace(/"/g, '').trim() };
      }).filter((row) => row.userName);
      const response = await importUsers({ users });
      const unknown = response?.unknown || response?.Unknown || [];
      setActionMessage(unknown.length ? `Unknown names: ${unknown.join(', ')}` : (response?.message || 'Import checked.'));
    } catch (err) {
      setActionMessage(s4Message(err));
    }
  };

  const handleDeleteUser = async (user) => {
    const signedIn = getLoggedinUserInfo();
    if (signedIn && String(signedIn.userId ?? signedIn.UserId) === String(user.userId)) {
      Swal.fire('Not allowed', 'You cannot delete the account you are signed in with.', 'info');
      return;
    }
    const label = [user.firstName, user.lastName].filter(Boolean).join(' ') || user.userName || 'this user';
    const confirm = await Swal.fire({
      title: 'Delete user?',
      text: `${label} will no longer be able to sign in.`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      confirmButtonText: 'Yes, delete',
    });
    if (!confirm.isConfirmed) return;
    try {
      const response = await deleteUserApi(user.userId);
      Swal.fire('Deleted', typeof response === 'string' ? response : 'User deleted successfully.', 'success');
      dispatch(getUserList({ queryString: searchQuery, PageNumber: currentPage, PageSize: pageSize }));
    } catch (err) {
      Swal.fire('Error', s4Message(err) || 'The user could not be deleted.', 'error');
    }
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
    setCurrentPage(1);
  };



  const rowStart = (currentPage - 1) * pageSize;

  document.title = 'List Users';

  return (
    <React.Fragment>
      <div className="page-content">
        <Container fluid>
          <Row>
            <Col lg={12}>
              <Card className="patient-list-modal admin-existance-list">
                <CardHeader className="border-0">
                  <div className="admin-list-toolbar d-flex align-items-center justify-content-between gap-2 flex-wrap w-100">
                    <div className="patient-list-modal__search flex-shrink-0">
                      <i className="ri-search-line patient-list-modal__search-icon" aria-hidden="true" />
                      <input
                        type="text"
                        className="form-control form-control-sm"
                        placeholder="Search..."
                        value={searchQuery}
                        onChange={handleSearchChange}
                      />
                    </div>
                    <div className="admin-list-toolbar__actions d-flex align-items-center gap-2 flex-shrink-0 ms-auto">
                      <input ref={fileRef} type="file" accept=".csv,text/csv" hidden onChange={handleImportFile} />
                      <button type="button" className="btn btn-sm admin-list-btn admin-list-btn--import" onClick={() => fileRef.current?.click()}>
                        <i className="ri-upload-2-line align-middle me-1" aria-hidden="true" />
                        Import
                      </button>
                      <button type="button" className="btn btn-sm admin-list-btn admin-list-btn--export" onClick={handleExport}>
                        <i className="ri-download-2-line align-middle me-1" aria-hidden="true" />
                        Export
                      </button>
                      <Link to="/admin/adduser" className="d-inline-flex">
                        <button type="button" className="btn btn-sm admin-list-btn admin-list-btn--new">
                          <i className="ri-add-line align-middle me-1" aria-hidden="true" />
                          New
                        </button>
                      </Link>
                    </div>
                  </div>
                </CardHeader>
                <CardBody>
                  <div className="table-responsive patient-list-modal__table-wrap">
                    <table className="table mb-0 align-middle patient-list-modal__table" id="customerTable">
                      <thead>
                        <tr>
                          <th scope="col" className="text-center" style={{ width: '5%' }}>#</th>
                          <th scope="col">First Name</th>
                          <th scope="col">Last Name</th>
                          <th scope="col">User Name</th>
                          <th scope="col">Email</th>
                          <th scope="col">Role</th>
                          <th scope="col">Status</th>
                          <th scope="col">Verification</th>
                          <th scope="col" className="text-center" style={{ width: '12%' }}>Action</th>
                        </tr>
                      </thead>
                      {userLoading ? (
                        <tbody>
                          <tr>
                            <td colSpan="9" className="text-center">
                              <Spinner color="primary" size="sm" />
                            </td>
                          </tr>
                        </tbody>
                      ) : (
                        <tbody>
                          {users?.length > 0 ? (
                            users.map((user, index) => (
                              <tr key={user.userId || index}>
                                <td className="text-center patient-list-modal__index">{rowStart + index + 1}</td>
                                <td>{user.firstName || '—'}</td>
                                <td>{user.lastName || '—'}</td>
                                <td>{user.userName || '—'}</td>
                                <td>{user.emailId || '—'}</td>
                                <td>{user.role || '—'}</td>
                                <td>{user.userStatus || '—'}</td>
                                <td>{verificationByUser[String(user.userId)] || '—'}</td>
                                <td className="text-center">
                                  <div className="d-inline-flex gap-2">
                                    <div className="edit">
                                      <Link to="/admin/edituser" state={{ userId: user.userId }}>
                                        <button type="button" className="btn btn-sm btn-soft-success edit-item-btn" title="Edit">
                                          <i className="ri-pencil-fill" />
                                        </button>
                                      </Link>
                                    </div>
                                    <div className="remove">
                                      <button
                                        type="button"
                                        className="btn btn-sm btn-soft-danger remove-item-btn"
                                        title="Delete"
                                        onClick={() => handleDeleteUser(user)}
                                      >
                                        <i className="ri-delete-bin-5-line" />
                                      </button>
                                    </div>
                                  </div>
                                </td>
                              </tr>
                            ))
                          ) : (
                            <tr>
                              <td colSpan="9" className="text-center text-muted py-4">
                                {searchQuery ? 'No users match your search' : 'No Users Found'}
                              </td>
                            </tr>
                          )}
                        </tbody>
                      )}
                    </table>
                  </div>

                  {actionMessage ? <div className="text-muted small mb-2">{actionMessage}</div> : null}
                  <div className="d-flex align-items-center justify-content-between patient-list-modal__footer">
                    <div className="text-muted patient-list-modal__footer-text">
                      {userLoading
                        ? 'Loading...'
                        : `Showing ${users.length} of ${totalRecords} Results · Page ${currentPage} of ${totalPages}`}
                    </div>
                                        <AdminListPagination
                      currentPage={currentPage}
                      totalPages={totalPages}
                      onPage={setCurrentPage}
                    />
                  </div>
                </CardBody>
              </Card>
            </Col>
          </Row>
        </Container>
      </div>
    </React.Fragment>
  );
};

export default ListUser;
